/**
 * Pipedrive Node - Version 2
 * Discriminator: resource=product, operation=search
 */


interface Credentials {
  pipedriveApi: CredentialReference;
  pipedriveOAuth2Api: CredentialReference;
}

/** Search deals */
export type PipedriveV2ProductSearchParams = {
  resource: 'product';
  operation: 'search';
  authentication?: 'apiToken' | 'oAuth2' | Expression<string>;
/**
 * The search term to look for. Minimum 2 characters (or 1 if using exact_match).
 */
    term: string | Expression<string> | PlaceholderValue;
/**
 * Whether only full exact matches against the given term are returned. It is not case sensitive.
 * @default false
 */
    exactMatch?: boolean | Expression<boolean>;
/**
 * Whether to return all results or only up to a given limit
 * @default false
 */
    returnAll?: boolean | Expression<boolean>;
/**
 * Max number of results to return
 * @displayOptions.show { returnAll: [false] }
 * @default 100
 */
    limit?: number | Expression<number>;
/**
 * Additional Fields
 * @default {}
 */
    additionalFields?: {
    /** Supports including optional fields in the results which are not provided by default
     */
    includeFields?: string | Expression<string> | PlaceholderValue;
    /** Fields to perform the search from. Defaults to all of them.
     * @default ["name","code","custom_fields"]
     */
    fields?: Array<'code' | 'custom_fields' | 'name'>;
  };
};

export type PipedriveV2ProductSearchNode = {
  type: 'n8n-nodes-base.pipedrive';
  version: 2;
  credentials?: Credentials;
  config: NodeConfig<PipedriveV2ProductSearchParams>;
};